def rearrange_bigger(n):
    def get_digits(s):
        return [int(d) for d in s]
    digits = get_digits(str(n))
    max_digit = max(digits)
    for i in range(len(digits)):
        if digits[i] < max_digit:
            digits[i], digits[-1-i] = digits[-1-i], digits[i]
    return str(int(digits))

